use super::KernelRule;

#[allow(clippy::too_many_lines)]
pub fn entries() -> Vec<KernelRule> {
    vec![
        // ── K: autotune dispatch — a generic autotuner wrapper's per-launch
        // cache-key REBUILD is the tax: build the equivalent key from values
        // already in the call frame (kernel + key-arg values + every arg's
        // dtype), memoize the chosen config once per key, and on hit launch
        // the RAW kernel fn with the config's own kwargs — bypassing the
        // wrapper entirely; a config carrying a pre_hook is never cached
        // (its per-launch side effect would be silently skipped). ──
        KernelRule {
            rule_id: "autotuner-key-memoized-per-launch-not-rebuilt".to_string(),
            gpu_concept: "MECHANISM (autotuner dispatch key memoized per launch — not rebuilt; category K — autotune dispatch): a hot kernel-launch path routed through a generic autotuner wrapper pays a per-launch HOST tax rebuilding the tuner's cache key — argument-name matching + dtype formatting on EVERY call — even after the tuner has already picked its config and nothing the key carries has changed. THE LAW, verbatim (the launch_autotuned docstring): 'Autotuner.run rebuilds its cache key on every launch, matching each argument name against a list and formatting the dtype of every tensor argument, several microseconds of host time per launch. This builds an equivalent key directly from kwargs: the values of the kernel's autotune key arguments plus the dtype (or None) of every argument.' — and the helper's own framing, verbatim: 'Launch a @triton.autotune kernel with the config it already picked.' THE KEY (built from values already in the call frame): 'key = (kernel, *[kwargs.get(name) for name in kernel.keys], *[getattr(arg, 'dtype', None) for arg in kwargs.values()])' — the kernel object itself, the VALUES of the kernel's declared autotune key arguments, and EVERY argument's dtype (None when the argument carries none); the PR body pins the equivalence, verbatim: 'It builds its cache key from the launch's own arguments (the values of the kernel's autotune `key` arguments plus each argument's dtype, the information Triton's key holds), so callers keep no key list and the selected config is unchanged.' — an EQUIVALENCE with the incumbent key semantics, not an approximation: the memoized key carries exactly the information the rebuilt key carried, so the same launches select the same configs. THE MEMOIZE-THEN-RAW-LAUNCH: a module-level dict '_autotuned_configs: dict[tuple, Any] = {}'; on miss the wrapper delegates once — 'kernel[grid](**kwargs)' — with the in-code comment, verbatim: '# Autotunes on the first launch for this key.' — then stores the winner '_autotuned_configs[key] = kernel.best_config'; on hit it launches the RAW kernel fn 'kernel.fn[grid](**kwargs, **config.all_kwargs())' and Autotuner.run never executes again for a warm key — the per-launch cost falls to a dict get + the config's own kwargs spread. THE PRE-HOOK REFUSAL: the config is cached ONLY 'if kernel.best_config.pre_hook is None:' — a config carrying a pre_hook needs that hook executed around EVERY launch, and the raw-fn bypass would silently skip it, so hook-bearing configs are never cached and their launches keep re-entering the tuning path: correctness is preserved by refusing to memoize a decision that is not replayable hook-free. THE COMPANION FACE (same commit): the classmethod is_arch_support_pdl gains '@cache' — a device-capability query answered once per process at the class, not at every call site: static device facts join stable dispatch keys as per-launch work that is identical every call and must be resolved once. MEASURED (source-reported, the PR #61497 body — the author's same-node claims, never our bar): host time of the prefill SSD scan plus its final-state write drops from '263 us to 179 us per Mamba layer' ('about 1.9 ms less per mixed step with 23 Mamba layers'); this memoization 'accounts for 43 of the 84 us saved per layer', same-node A/B '+1.0% to +2.5% OTPS/gpu at concurrency 4-64 (+2.5% at 64) and flat at 1-2 and 128'; end to end 'Up to 1.08x output throughput (OTPS/gpu) on 1x B200' (1.04-1.08x at concurrency 4-64, 1.02x at 128, 1.01x at 1-2). DECISION CONTENT: (a) a dispatcher's per-launch cost is dominated by REBUILDING identity for a lookup whose answer is stable — build the key from cheap values already in the call frame (the key-arg values + every arg's dtype) and memoize the DECISION (the config), never the data; (b) on hit, bypass the wrapper class entirely — call the raw kernel fn with the cached config's own kwargs (config.all_kwargs()), exactly what the wrapper would have done after its rebuild; (c) the refusal clause is load-bearing: memoize only decisions replayable without their per-launch side effects (a pre_hook is one, so a hook-bearing config is never cached); (d) the hand-built key is version-coupled to the incumbent autotuner's key semantics ('the information Triton's key holds') — when that format changes, the key must be re-derived, else a stale hit answers for a launch it no longer matches. CLASS SIGNATURE: a per-launch dispatch wrapper whose cache-key construction (argument-name matching, dtype formatting, tuple/string building) is measurable host work on a path whose tuned decision is stable per key. REGIME: eager serving paths where a kernel-launch layer runs per step (the source's Mamba2 mixer runs eagerly in prefill and mixed prefill+decode steps, so its host overhead lands directly on step latency), Python/Triton autotuner fronts, any Rust dispatch site rebuilding a HashMap key or formatting a config string per call. ANTI-REGIME: configs carrying pre-hooks (the refusal — never cached, correctly); autotuners whose key semantics the hand-built key does not mirror exactly (a wrong warm hit is worse than the µs tax); unbounded launch diversity (the map grows per distinct key — bounded here by shape/dtype diversity, but a key arg whose VALUE is unbounded re-tunes per value by design); cold paths (the wrapper runs once; the memoization is dead weight). KINSHIP (grep over src/domains/kernel_opt/corpus/, named): autotune-fidelity-synthetic-carries-producer-params (B223, entries_gpu_87) owns key CONTENT fidelity — what the tuner MEASURED (producer params, DRAM streaming, noise margin, the full mechanism signature) — and its Batch-237 HARDWARE-PATH rider owns the key CONTENT adapter/API axis (the fingerprint + API in the persisted namespace): BOTH legislate what a key must CARRY; THIS owns the per-launch COST of constructing an equivalent key and replaying its answer raw (content assumed correct, construction made free) — compose: a key must first carry the right axes (their law), then stop paying to rebuild it every launch (this law). hot-swap-weights-preserve-autotune-caches (B02, entries_gpu_02) owns cache preservation ACROSS weight swaps and autotune-cache-extract-outlives-owner (B05, entries_gpu_05) owns cache lifetime ACROSS owner destruction — THIS never touches cache lifetime; it deletes the per-launch rebuild INSIDE one owner's steady state. pipeline-cache-key-covers-every-function-constant (B129) owns cache-key COMPLETENESS for compiled pipeline variants — the same key instinct one axis over: that rule GROWS keys to stay correct, this one builds the complete key cheaply. swept-shape-bucket-launch-tables (B104) ships OFFLINE sweeps as data tables (no runtime tuner at all); env-flag-resolved-once-not-per-dispatch (B38) is the resolve-once law for decision inputs — the @cache companion face is its device-capability instance. GREP EVIDENCE: 'Autotuner.run|all_kwargs|pre_hook|best_config|is_arch_support_pdl' → ZERO corpus hits; 'launch_autotuned' → entries_popcorn only (autotune-aggregate-workload-key's fixture fn launch_autotuned_aggregate — a launch-config selector, a different sense, no key memoization). NotBenchable here (host launch-path overhead, µs class, source-reported only — the PR-body numbers above are the author's same-node claims; a Python launch-path microbench is not this box's lane and no wall-clock bar is asserted; the decision content is verifiable by inspection of any dispatch wrapper). Source: vllm-project/vllm @ e4a676cdc22f99e808093a87ff8509a6089d392d (#61497 '[Perf][Mamba] Reduce host overhead in the Mamba2 Triton SSD prefill path', merged 2026-10-20, Apache-2.0) -- vllm/model_executor/layers/mamba/ops/triton_helpers.py (launch_autotuned + _autotuned_configs) + vllm/platforms/cuda.py (is_arch_support_pdl @cache). Batch 265 / Plan 269. PR body fetched 2026-10-20; every quote verbatim at the pin.".to_string(),
            ref_shape: "// naive: every launch re-enters the generic autotuner wrapper, which\n// REBUILDS the cache key from scratch — matching each argument NAME\n// against the kernel's key list and FORMATTING the dtype of every\n// tensor argument — several microseconds of host time per launch,\n// paid on EVERY launch even though the tuned decision is stable\n// after the first.\nuse std::collections::HashMap;\nuse std::sync::atomic::{AtomicUsize, Ordering};\nuse std::sync::OnceLock;\n\nstatic NAME_MATCHES: AtomicUsize = AtomicUsize::new(0);\nstatic DTYPE_FORMATS: AtomicUsize = AtomicUsize::new(0);\nstatic WRAPPER_ENTRIES: AtomicUsize = AtomicUsize::new(0);\n\n#[derive(Clone, Copy, PartialEq, Eq, Debug)]\n#[allow(dead_code)] // F16 unused HERE — the optimized fixture exercises it\nenum DType {\n    F32,\n    F16,\n}\n\nstruct Arg {\n    name: &'static str,\n    value: u64,           // the payload an autotune key arg names\n    dtype: Option<DType>, // None for non-tensors — 'or None'\n}\n\nstruct Args(Vec<Arg>);\n\nimpl Args {\n    fn get(&self, name: &str) -> Option<u64> {\n        self.0.iter().find(|a| a.name == name).map(|a| a.value)\n    }\n    fn values(&self) -> std::slice::Iter<'_, Arg> {\n        self.0.iter()\n    }\n}\n\n#[derive(Clone)]\nstruct Config {\n    block: usize,\n}\n\nimpl Config {\n    fn all_kwargs(&self) -> Vec<(&'static str, usize)> {\n        vec![(\"BLOCK_SIZE\", self.block)]\n    }\n}\n\nstruct Kernel {\n    keys: &'static [&'static str], // the autotune key arg names\n    best_config: OnceLock<Config>, // what the tuner already picked\n}\n\nimpl Kernel {\n    fn tune(&self) -> Config {\n        // the tuner runs ONCE; the config is stable afterwards\n        self.best_config.get_or_init(|| Config { block: 128 }).clone()\n    }\n    fn dispatch(&self, grid: (usize, usize, usize), kwargs: &Args, cfg: &Config) -> usize {\n        let _ = (grid, cfg.all_kwargs(), kwargs);\n        1 // one device launch\n    }\n}\n\n// the generic Autotuner::run shape: rebuild the key, look up, dispatch\nfn autotuner_run(\n    kernel: &Kernel,\n    grid: (usize, usize, usize),\n    kwargs: &Args,\n    cache: &mut HashMap<String, Config>,\n) -> usize {\n    WRAPPER_ENTRIES.fetch_add(1, Ordering::SeqCst); // the wrapper class runs EVERY launch\n    // THE TAX: rebuild the cache key on every launch —\n    let mut key = format!(\"{:p}\", kernel);\n    for name in kernel.keys {\n        NAME_MATCHES.fetch_add(1, Ordering::SeqCst); // ...matching each argument NAME\n        let v = kwargs.get(name);\n        key.push_str(&format!(\"|{name}={v:?}\"));\n    }\n    for arg in kwargs.values() {\n        DTYPE_FORMATS.fetch_add(1, Ordering::SeqCst); // ...formatting EVERY arg's dtype\n        let d = match arg.dtype {\n            Some(d) => format!(\"{d:?}\"),\n            None => \"None\".to_string(),\n        };\n        key.push_str(&format!(\"|{d}\"));\n    }\n    match cache.get(&key) {\n        Some(config) => kernel.dispatch(grid, kwargs, config),\n        None => {\n            let config = kernel.tune(); // autotunes on the first launch for this key\n            cache.insert(key, config.clone());\n            kernel.dispatch(grid, kwargs, &config)\n        }\n    }\n}\n\n#[test]\nfn the_wrapper_rebuilds_an_identical_key_on_every_launch() {\n    let kernel = Kernel {\n        keys: &[\"dim\", \"chunk_size\"],\n        best_config: OnceLock::new(),\n    };\n    let kwargs = || Args(vec![\n        Arg { name: \"states_ptr\", value: 0x1000, dtype: Some(DType::F32) },\n        Arg { name: \"out_ptr\", value: 0x2000, dtype: Some(DType::F32) },\n        Arg { name: \"dim\", value: 64, dtype: None },\n        Arg { name: \"chunk_size\", value: 128, dtype: None },\n    ]);\n    let mut cache = HashMap::new();\n    let a = autotuner_run(&kernel, (1, 1, 1), &kwargs(), &mut cache);\n    let b = autotuner_run(&kernel, (1, 1, 1), &kwargs(), &mut cache);\n    assert_eq!(a, b);\n    // the decision was stable after launch one — the wrapper still ran\n    // and rebuilt the identical key both times:\n    assert_eq!(WRAPPER_ENTRIES.load(Ordering::SeqCst), 2);\n    assert_eq!(NAME_MATCHES.load(Ordering::SeqCst), 4, \"2 key args x 2 launches\");\n    assert_eq!(DTYPE_FORMATS.load(Ordering::SeqCst), 8, \"4 args x 2 launches\");\n    assert_eq!(cache.len(), 1, \"one key, one config — the second rebuild was pure tax\");\n}\n".to_string(),
            opt_pattern: "// optimized: build the EQUIVALENT key from values already in the call\n// frame — the kernel object, the VALUES of the kernel's autotune key\n// arguments, and every argument's dtype (or None) — memoize the chosen\n// config, and on hit launch the RAW kernel fn with the config's own\n// kwargs. The wrapper never runs for a warm key; a config that carries\n// a pre_hook is never cached (the raw launch would skip its per-launch\n// side effect); the device-capability query joins as @cache — resolved\n// once, not per call.\nuse std::collections::HashMap;\nuse std::sync::atomic::{AtomicUsize, Ordering};\nuse std::sync::OnceLock;\n\n#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]\nenum DType {\n    F32,\n    F16,\n}\n\n#[derive(Clone, PartialEq, Eq, Hash)]\nstruct CacheKey {\n    kernel: &'static str,                       // the kernel object's identity\n    key_args: Vec<(&'static str, Option<u64>)>, // kwargs.get(name) per kernel.keys\n    arg_dtypes: Vec<Option<DType>>,             // getattr(arg, 'dtype', None), call order\n}\n\nstruct Arg {\n    name: &'static str,\n    value: u64,\n    dtype: Option<DType>,\n}\n\nstruct Args(Vec<Arg>);\n\nimpl Args {\n    fn get(&self, name: &str) -> Option<u64> {\n        self.0.iter().find(|a| a.name == name).map(|a| a.value)\n    }\n    fn values(&self) -> std::slice::Iter<'_, Arg> {\n        self.0.iter()\n    }\n}\n\n#[derive(Clone)]\nstruct Config {\n    block: usize,\n    pre_hook: Option<&'static str>, // a per-launch side effect, when present\n}\n\nimpl Config {\n    fn all_kwargs(&self) -> Vec<(&'static str, usize)> {\n        vec![(\"BLOCK_SIZE\", self.block)]\n    }\n}\n\n// per-call-site state stands in for the module-level _autotuned_configs\n// dict so each test owns an isolated instance\nstruct Ctx {\n    configs: HashMap<CacheKey, Config>,\n    tuner_entries: usize,\n    raw_launches: usize,\n}\n\nimpl Ctx {\n    fn new() -> Self {\n        Self { configs: HashMap::new(), tuner_entries: 0, raw_launches: 0 }\n    }\n}\n\nstruct Kernel {\n    name: &'static str,\n    keys: &'static [&'static str],\n    best_config: OnceLock<Config>,\n}\n\nimpl Kernel {\n    /// the miss arm: kernel[grid](**kwargs) — autotunes once per key\n    fn autotune_launch(&self, ctx: &mut Ctx, grid: (usize, usize, usize), kwargs: &Args) -> Config {\n        let _ = (grid, kwargs);\n        ctx.tuner_entries += 1;\n        self.best_config\n            .get_or_init(|| Config { block: 128, pre_hook: None })\n            .clone()\n    }\n    /// the hit arm: kernel.fn[grid](**kwargs, **config.all_kwargs())\n    fn raw_launch(\n        &self,\n        ctx: &mut Ctx,\n        grid: (usize, usize, usize),\n        kwargs: &Args,\n        config: &Config,\n    ) -> usize {\n        let _ = (grid, config.all_kwargs(), kwargs);\n        ctx.raw_launches += 1;\n        if let Some(hook) = config.pre_hook {\n            // the wrapper would run this EVERY launch — a raw launch\n            // must NOT silently skip it (why hook-bearing configs are\n            // never cached)\n            run_pre_hook(hook);\n        }\n        1\n    }\n}\n\nfn run_pre_hook(_hook: &'static str) {}\n\nfn launch_autotuned(ctx: &mut Ctx, kernel: &Kernel, grid: (usize, usize, usize), kwargs: &Args) -> usize {\n    // the key: kernel + the autotune key args' VALUES + every arg's dtype\n    let key = CacheKey {\n        kernel: kernel.name,\n        key_args: kernel.keys.iter().map(|name| (*name, kwargs.get(name))).collect(),\n        arg_dtypes: kwargs.values().map(|a| a.dtype).collect(),\n    };\n    let cached = ctx.configs.get(&key).cloned();\n    let config = match cached {\n        Some(c) => c,\n        None => {\n            // Autotunes on the first launch for this key.\n            let c = kernel.autotune_launch(ctx, grid, kwargs);\n            if c.pre_hook.is_none() {\n                // THE PRE-HOOK REFUSAL: only replayable configs are cached\n                ctx.configs.insert(key, c.clone());\n            }\n            return kernel.raw_launch(ctx, grid, kwargs, &c);\n        }\n    };\n    kernel.raw_launch(ctx, grid, kwargs, &config) // bypasses Autotuner::run\n}\n\n// the companion face: @cache on the device-capability query — one\n// driver query per process, not per call site\nfn is_arch_support_pdl(query: impl FnOnce() -> bool, cache: &OnceLock<bool>) -> bool {\n    *cache.get_or_init(query)\n}\n\n#[test]\nfn a_warm_launch_skips_the_key_rebuild_and_the_wrapper() {\n    let kernel = Kernel {\n        name: \"ssd_state_passing\",\n        keys: &[\"dim\", \"chunk_size\"],\n        best_config: OnceLock::new(),\n    };\n    let kwargs = || Args(vec![\n        Arg { name: \"states_ptr\", value: 0x1000, dtype: Some(DType::F32) },\n        Arg { name: \"out_ptr\", value: 0x2000, dtype: Some(DType::F32) },\n        Arg { name: \"dim\", value: 64, dtype: None },\n        Arg { name: \"chunk_size\", value: 128, dtype: None },\n    ]);\n    let mut ctx = Ctx::new();\n    let a = launch_autotuned(&mut ctx, &kernel, (1, 1, 1), &kwargs());\n    let b = launch_autotuned(&mut ctx, &kernel, (1, 1, 1), &kwargs());\n    let c = launch_autotuned(&mut ctx, &kernel, (1, 1, 1), &kwargs());\n    assert_eq!((a, b, c), (1, 1, 1));\n    // the tuner ran exactly once; every later launch went RAW\n    assert_eq!(ctx.tuner_entries, 1);\n    assert_eq!(ctx.raw_launches, 3);\n    assert_eq!(ctx.configs.len(), 1, \"one key -> one memoized config\");\n}\n\n#[test]\nfn a_dtype_change_is_a_different_key_not_a_wrong_hit() {\n    let kernel = Kernel {\n        name: \"ssd_state_passing\",\n        keys: &[\"dim\", \"chunk_size\"],\n        best_config: OnceLock::new(),\n    };\n    let mut ctx = Ctx::new();\n    let f32_args = Args(vec![\n        Arg { name: \"states_ptr\", value: 0x1000, dtype: Some(DType::F32) },\n        Arg { name: \"out_ptr\", value: 0x2000, dtype: Some(DType::F32) },\n        Arg { name: \"dim\", value: 64, dtype: None },\n        Arg { name: \"chunk_size\", value: 128, dtype: None },\n    ]);\n    let f16_args = Args(vec![\n        Arg { name: \"states_ptr\", value: 0x1000, dtype: Some(DType::F16) },\n        Arg { name: \"out_ptr\", value: 0x2000, dtype: Some(DType::F16) },\n        Arg { name: \"dim\", value: 64, dtype: None },\n        Arg { name: \"chunk_size\", value: 128, dtype: None },\n    ]);\n    let _ = launch_autotuned(&mut ctx, &kernel, (1, 1, 1), &f32_args);\n    let _ = launch_autotuned(&mut ctx, &kernel, (1, 1, 1), &f16_args);\n    // two dtypes -> two keys -> two tuner entries; the F32 hit never\n    // answers for the F16 launch\n    assert_eq!(ctx.tuner_entries, 2);\n    assert_eq!(ctx.configs.len(), 2);\n}\n\n#[test]\nfn pre_hook_configs_are_never_cached() {\n    let kernel = Kernel {\n        name: \"hooked\",\n        keys: &[\"dim\"],\n        best_config: OnceLock::new(),\n    };\n    kernel\n        .best_config\n        .set(Config { block: 64, pre_hook: Some(\"zero_scratch\") })\n        .unwrap_or_else(|_| panic!(\"set once\"));\n    let kwargs = Args(vec![Arg { name: \"dim\", value: 64, dtype: None }]);\n    let mut ctx = Ctx::new();\n    let _ = launch_autotuned(&mut ctx, &kernel, (1, 1, 1), &kwargs);\n    let _ = launch_autotuned(&mut ctx, &kernel, (1, 1, 1), &kwargs);\n    // the refusal: the cache stays EMPTY, so every launch re-enters the\n    // tuning path and the hook keeps running — correctness over speed\n    assert!(ctx.configs.is_empty(), \"hook-bearing config refused\");\n    assert_eq!(ctx.tuner_entries, 2, \"every launch re-tunes\");\n    assert_eq!(ctx.raw_launches, 2, \"the launch itself still ran, hook included\");\n}\n\n#[test]\nfn the_capability_query_is_answered_once() {\n    static QUERIES: AtomicUsize = AtomicUsize::new(0);\n    let cache: OnceLock<bool> = OnceLock::new();\n    let pdl = || {\n        is_arch_support_pdl(\n            || {\n                QUERIES.fetch_add(1, Ordering::SeqCst);\n                true // the one driver query\n            },\n            &cache,\n        )\n    };\n    assert!(pdl() && pdl() && pdl());\n    assert_eq!(QUERIES.load(Ordering::SeqCst), 1, \"@cache: one query, many call sites\");\n}\n".to_string(),
        },
    ]
}
